<?php session_name('VS_CUSTOMER');session_start();if(!isset($_SESSION['user_id'])||($_SESSION['user_role']??'')!=='user'){header('Location: login.php');exit;}require_once 'includes/header.php';?>
<section class="page-shell narrow"><span class="eyebrow dark">MY PROFILE</span><h1>Account details</h1><div class="profile-card"><div class="avatar"><?php echo strtoupper(substr($_SESSION['user_name']??'U',0,1));?></div><form id="profileForm" class="profile-form"><div id="msg"></div><label>Full name<input id="name" required></label><label>Email address<input id="email" type="email" readonly><small>Email is your login ID and cannot be changed here.</small></label><label>Phone number<input id="phone" placeholder="10-digit mobile number"></label><label>Driving licence number<input id="license" placeholder="Driving licence number"></label><label>Address<textarea id="address" rows="3" placeholder="Your address"></textarea></label><button class="btn">Save profile</button></form></div></section>
<script>
const profileForm=document.getElementById('profileForm'),profileMsg=document.getElementById('msg');
async function loadProfile(){try{const j=await fetch('api/auth/profile-details.php',{credentials:'include'}).then(r=>r.json());if(j.success){document.getElementById('name').value=j.data.name||'';document.getElementById('email').value=j.data.email||'';document.getElementById('phone').value=j.data.phone||'';document.getElementById('license').value=j.data.license||'';document.getElementById('address').value=j.data.address||''}}catch(_){profileMsg.innerHTML='<div class="message error">Unable to load profile.</div>'}}
profileForm.addEventListener('submit',async e=>{e.preventDefault();const data={name:document.getElementById('name').value.trim(),phone:document.getElementById('phone').value.trim(),license:document.getElementById('license').value.trim(),address:document.getElementById('address').value.trim()};try{const j=await fetch('api/auth/profile-details.php',{method:'PUT',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify(data)}).then(r=>r.json());profileMsg.innerHTML=`<div class="message ${j.success?'success':'error'}">${j.message}</div>`}catch(_){profileMsg.innerHTML='<div class="message error">Unable to save profile.</div>'}});loadProfile();
</script><?php require_once 'includes/footer.php';?>
